const STAT={cards:['<rect x="3.5" y="1.5" width="7" height="11" rx="1.5"/>','resource cards'],dev:['<rect x="3.5" y="1.5" width="7" height="11" rx="1.5"/><path d="M7 4.6l1.9 2.4L7 9.4 5.1 7z" fill="currentColor" stroke="none"/>','development cards'],knights:['<path d="M7 1.5l5 2v3.8c0 3-2.3 4.8-5 5.7-2.7-.9-5-2.7-5-5.7V3.5z"/>','knights played'],route:['<path d="M1.5 11.5 6 7l2 2 4.5-5.5"/>','road length']};
