function lobbyWait(){const unready=state.players.filter(p=>!p.ready).map(p=>p.id===state.players[state.me]?.id?'you':p.name);if(state.players.length<2)return 'Waiting for at least one more player to join.';if(unready.length)return `Waiting for ${unready.length>1?unready.slice(0,-1).join(', ')+' and '+unready.at(-1):unready[0]} to get ready.`;return '';}
function home(){return `${header()}<main class="landing"><section class="intro"><div class="eyebrow">THE TABLE IS YOURS</div><h1>Small island.<br><em>Big plans.</em></h1><p>A handful of resources. A few friendly rivals.<br>Build your way to something great, one road at a time.</p>${illustratedBoard()}</section><section class="form-card"><div class="tabs"><button data-ui="tab-create" class="${tab==='create'?'selected':''}">Create a table</button><button data-ui="tab-join" class="${tab==='join'?'selected':''}">Join friends</button></div><h2>${tab==='create'?'Make room for everyone.':'Your seat is waiting.'}</h2><p class="muted" style="font-size:13px">${tab==='create'?'Start a private game and send your friends an invite.':'Enter your invitation code to settle in.'}</p><form id="entry"><label for="nickname">YOUR NAME</label><input id="nickname" name="name" placeholder="What should we call you?" maxlength="24" required autocomplete="nickname">${tab==='create'?`<div class="split"><div><label for="map">MAP</label><select name="map" id="map"><option value="base" selected>Base · 2–4</option><option value="extended">Extended · 2–6</option></select></div><div><label for="setup">ISLAND SETUP</label><select id="setup" name="setup"><option value="variable">Variable island</option><option value="fixed">Fixed island</option></select></div></div>`:`<label for="code">INVITATION CODE</label><input id="code" name="code" value="${escape(room)}" placeholder="12-character room code" pattern="[a-fA-F0-9]{12}" required maxlength="12">`}<button class="primary wide">${tab==='create'?'Create a private table':'Join the table'} <span style="float:right">${ui('arrow')}</span></button></form><p class="fine" style="margin:18px 0 0">2–6 friends · No account needed · Your game saves automatically</p>${Object.keys(saved).length?`<div style="margin-top:20px;border-top:1px solid var(--line);padding-top:15px"><div class="eyebrow muted" style="margin-bottom:10px">YOUR SAVED SEATS</div>${Object.keys(saved).sort((a,b)=>(saved[b].at||0)-(saved[a].at||0)).slice(0,5).map(id=>`<button class="ghost small" style="margin:3px" data-resume="${id}">${id} ${ui('external')}</button>`).join('')}</div>`:''}</section></main><footer class="landing-footer"><span>⬡ &nbsp; Classic island strategy</span><span>${ui('swap')} &nbsp; Trade, build, settle</span><span>◷ &nbsp; An evening well spent</span></footer>`;}
function lobby(){const me=state.players[state.me],seats=Array.from({length:state.seats},(_,i)=>{const p=state.players[i];if(!p)return `<div class="lobby-seat empty">＋ &nbsp; Open seat</div>`;
    const pose=p.ready?'':' transform="rotate(-78) translate(-6 -2)"';
    return `<div class="lobby-seat${p.ready?' is-ready':''}" style="--player:${p.color};--mat:${tint(p.color,.8)}"><svg class="seat-pieces" viewBox="-22 -22 56 40" width="56" height="40" aria-hidden="true"><g transform="translate(-8 6)"><g${pose}>${piece('settlement',p.color)}</g></g><g transform="translate(12 6)"><g${pose}>${piece('settlement',p.color)}</g></g></svg><span class="player-name">${escape(p.name)} ${i===state.me?'(you)':''}<br><small class="muted">${i===0?'Table host':'Seat '+(i+1)}</small></span><span class="badge ${p.ready?'ready':''}">${p.ready?`Ready ${ui('check')}`:'Not ready yet'}</span></div>`;}).join('');
  return `${header()}<main class="lobby"><div class="lobby-top"><div><div class="eyebrow muted" style="margin-bottom:15px">YOUR PRIVATE TABLE</div><h1>A good game starts<br>with good company.</h1></div><div class="pill">${state.players.length} / ${state.seats} seats filled</div></div><div class="lobby-grid"><section class="lobby-table">${illustratedBoard(true)}<div class="lobby-seats">${seats}</div></section><section class="form-card place-card"><h2>Almost an island.</h2><p class="muted" style="font-size:13px">${state.setup==='fixed'?'Fixed terrain and starting placements':'A fresh island with two rounds of settlement placement'}. ${state.map==='extended'?'Extended island for up to 6; 5 or 6 players take paired-player turns.':'Base island for up to 4.'} Start with 2 or more.</p><label>INVITATION CODE</label><input class="place-code" readonly value="${state.id}" aria-label="Invitation code"><button class="ghost wide" data-ui="invite">Copy invitation link ${ui('external')}</button><button class="${me.ready?'ghost':'gold'} wide" data-command="ready">${me.ready?'Not ready yet':`Stand my pieces up · I’m ready ${ui('check')}`}</button>${state.me===0?`<button class="primary wide" data-command="start" ${lobbyWait()?'disabled':''}>Set sail ${ui('arrow')}</button>`:''}<p class="fine" data-ui="start-hint" style="margin-top:12px">${escape(lobbyWait()||(state.me===0?`Everyone is ready. Set sail now${state.players.length<state.seats?', or wait for more friends to join':''}.`:'Everyone is ready. Waiting for the host to set sail.'))}</p><p class="fine" style="margin:18px 0 0">Your seat is saved in this browser. To keep playing on another phone or computer, use the button below.</p><button class="ghost small" data-ui="seat">Play on another device</button></section></div></main>`;}
// Number token: the number on top, its probability dots on a row of their own beneath it, inside a larger disc.
function token(h){const n=6-Math.abs(7-h.number),red=[6,8].includes(h.number),cy=h.y+11;return `<circle class="number-edge" cx="${h.x}" cy="${cy+2}" r="23"/><circle class="number" cx="${h.x}" cy="${cy}" r="23"/><text class="number-text${red?' red-number':''}" x="${h.x}" y="${cy-4}">${h.number}</text>${Array.from({length:n},(_,i)=>`<circle class="pip${red?' red-pip':''}" cx="${(h.x+(i-(n-1)/2)*5.6).toFixed(1)}" cy="${cy+13}" r="1.9"/>`).join('')}`;}
function board(){const b=state.board,ys=b.vertices.map(v=>v.y),xs=b.vertices.map(v=>v.x),width=Math.max(...xs)-Math.min(...xs)+152,height=Math.max(...ys)-Math.min(...ys)+152;const active=state.active===state.me,won=state.phase==='finished';
  const outline=hull(b.vertices);let html=`<svg class="board" viewBox="${-width/2} ${-height/2} ${width} ${height}" role="img" aria-label="Game board. Select highlighted roads or intersections to build."><defs><filter id="shadow" x="-10%" y="-10%" width="120%" height="125%"><feDropShadow dx="0" dy="10" stdDeviation="9" flood-color="#2a1c10" flood-opacity=".45"/></filter><filter id="glow" x="-60%" y="-60%" width="220%" height="220%"><feDropShadow dx="0" dy="0" stdDeviation="3.2" flood-color="#ffd25e" flood-opacity="1"/></filter><radialGradient id="sea" r=".75"><stop offset="0" stop-color="#6ba7bd"/><stop offset="1" stop-color="#3b7895"/></radialGradient></defs>`;
  // Sea inside a wooden frame, with a few painted wave marks; the island sits on it like tiles in a box.
  html+=`<g filter="url(#shadow)"><polygon points="${grow(outline,64)}" fill="#6d4628" stroke="#6d4628" stroke-width="16" stroke-linejoin="round"/><polygon points="${grow(outline,58)}" fill="url(#sea)" stroke="#a5764a" stroke-width="7" stroke-linejoin="round"/></g><polygon points="${grow(outline,61)}" fill="none" stroke="#c99a68" stroke-width="1.5" stroke-linejoin="round" opacity=".8"/>`;
  html+=outline.map((p,i)=>{const q=outline[(i+1)%outline.length],m={x:(p.x+q.x)/2,y:(p.y+q.y)/2},l=Math.hypot(m.x,m.y)||1,x=m.x+m.x/l*30,y=m.y+m.y/l*30;return i%2?'':`<path class="wave" d="M${(x-9).toFixed(1)} ${y.toFixed(1)}q3 -3.5 6 0t6 0t6 0"/>`;}).join('');
  for(const h of b.hexes){const pts=h.vertices.map(v=>`${b.vertices[v].x},${b.vertices[v].y}`).join(' '),under=h.vertices.map(v=>`${b.vertices[v].x},${b.vertices[v].y+4}`).join(' ');html+=`<polygon points="${under}" fill="${tint(terrain[h.resource],-.38)}"/><g class="tile" data-tip="${hexTip(h)}"><polygon class="hex" data-tile="${h.id}" points="${pts}" fill="${terrain[h.resource]}"/>${h.number?`<use href="#ico-${h.resource}" x="${h.x-14}" y="${h.y-43}" width="28" height="28"/>`:`<use href="#ico-${h.resource}" x="${h.x-23}" y="${h.y-30}" width="46" height="46"/>`}${h.number?token(h):''}</g>`;}
  // Producing hexes glow after a roll's tumble; starting resources glow at once (the glow is shifted past the tumble's 800 ms).
  const roll=effect('roll',2600),lit=[...(roll?[[roll,0]]:[]),...effects.filter(f=>f.kind!=='roll'&&f.gains&&since(f)<1800).map(f=>[f,800])];
  for(const [f,skip] of lit)for(const id of new Set((f.gains||[]).map(g=>g.hex))){const h=b.hexes[id];html+=`<polygon class="hex-glow" style="--t:-${since(f)+skip}ms" points="${h.vertices.map(v=>`${b.vertices[v].x},${b.vertices[v].y}`).join(' ')}"/>`;}
  // Ports are parchment tags on the water, joined to their two shore corners by wooden piers.
  for(const port of b.ports){const vs=port.vertices.map(v=>b.vertices[v]);const x=(vs[0].x+vs[1].x)/2,y=(vs[0].y+vs[1].y)/2,scale=1+36/Math.hypot(x,y),px=x*scale,py=y*scale;html+=`<g class="port-g" data-tip="${portTip(port)}">`+vs.map(v=>`<path class="pier" d="M${v.x} ${v.y}L${px} ${py}"/>`).join('')+`<rect class="port" x="${px-23}" y="${py-14}" width="46" height="28" rx="7"/>${port.resource==='any'?`<text class="port-text" x="${px}" y="${py-2}">3:1</text>`:`<use href="#ico-${port.resource}" x="${px-19}" y="${py-13}" width="14" height="14"/><text class="port-text" x="${px+6}" y="${py-2}">2:1</text>`}<text class="port-text" x="${px}" y="${py+9}" style="font-size:7px">${port.resource==='any'?'ANY':port.resource.toUpperCase()}</text></g>`;}
  // What another player just placed (or where they moved the robber) pulses in their colour for 3 s; road glows go under the roads, rings over the pieces.
  const placed=effects.filter(f=>f.p!==state.me&&f.p>=0&&since(f)<3000&&(f.kind==='build'||f.kind==='robber')).map(f=>[f,`style="--t:-${since(f)}ms;--c:${state.players[f.p]?.color}"`]);
  for(const [f,t] of placed)if(f.kind==='build'&&f.edge!=null){const [v,w]=b.edges[f.edge].vertices.map(i=>b.vertices[i]);html+=`<line class="placed placed-road" data-placed="edge" ${t} x1="${v.x}" y1="${v.y}" x2="${w.x}" y2="${w.y}"/>`;}
  // Roads are raised wooden bars, shortened at both ends so they meet the pieces instead of overlapping them.
  for(const e of b.edges){const [v,w]=e.vertices.map(i=>b.vertices[i]);if(e.owner!==null){const c=state.players[e.owner].color,k=.16,x1=v.x+(w.x-v.x)*k,y1=v.y+(w.y-v.y)*k,x2=w.x-(w.x-v.x)*k,y2=w.y-(w.y-v.y)*k,seg=`x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"`;html+=`<g class="road${won&&e.owner===state.winner?' winner-piece':''}" data-road="${e.id}" data-owner="${e.owner}" data-tip="${roadTip(e)}"${won&&e.owner===state.winner?' filter="url(#glow)"':''}><line ${seg} transform="translate(0 2)" stroke="#1f1a14" stroke-opacity=".35" stroke-width="6"/><line ${seg} stroke="#2a2119" stroke-width="6.6"/><line ${seg} stroke="${c}" stroke-width="4.2"/><line ${seg} transform="translate(0 -.8)" stroke="${tint(c,.45)}" stroke-width="1.2"/></g>`;}if(active&&(mode==='road'||['setupRoad','freeRoads'].includes(state.phase))&&state.legal.roads.includes(e.id))html+=`<line class="road-target legal" x1="${v.x}" y1="${v.y}" x2="${w.x}" y2="${w.y}" data-edge="${e.id}" tabindex="0" role="button" aria-label="Build road ${e.id}"/>`;}
  for(const v of b.vertices){if(v.building){const c=v.building.owner<0?'#8a8f80':state.players[v.building.owner].color;html+=`<g class="building" data-owner="${v.building.owner}" data-kind="${v.building.kind}" data-tip="${buildingTip(v)}" transform="translate(${v.x},${v.y})">${piece(v.building.kind,c,won&&v.building.owner===state.winner)}</g>`;}if(active&&((mode==='settlement'||state.phase==='setupSettlement')&&state.legal.settlements.includes(v.id)||mode==='city'&&state.legal.cities.includes(v.id)))html+=`<circle class="vertex-target" cx="${v.x}" cy="${v.y}" r="7" data-vertex="${v.id}" tabindex="0" role="button" aria-label="${mode==='city'?'Upgrade city':'Place settlement'} ${v.id}"/>`;}
  // The robber is a grey pawn standing on its tile beside the number it blocks, which is dimmed.
  const robber=b.hexes[state.robber];if(robber.number)html+=`<circle cx="${robber.x}" cy="${robber.y+11}" r="23" fill="#1f1a14" opacity=".28"/>`;html+=`<g class="robber" transform="translate(${robber.x+(robber.number?33:0)},${robber.y+(robber.number?24:18)})" aria-label="Robber"><ellipse cx="0" cy="1" rx="11" ry="3.6" fill="#1f1a14" opacity=".35"/><path d="M-10 0Q-11 -6 -6 -10L-4 -22A8.5 8.5 0 1 1 4 -22L6 -10Q11 -6 10 0Z" fill="#5e615e" stroke="#1d1e1c" stroke-width="1.6" stroke-linejoin="round"/><path d="M-6 -3Q-7 -7 -3 -10L-2 -20" stroke="#a3a6a0" stroke-width="2.4" fill="none" stroke-linecap="round"/><circle cx="-2.6" cy="-30" r="2.4" fill="#b3b6af"/></g>`;
  if(active&&state.phase==='robber')for(const h of b.hexes)if(h.id!==state.robber)html+=`<polygon class="hex-target" points="${h.vertices.map(v=>`${b.vertices[v].x},${b.vertices[v].y}`).join(' ')}" data-hex="${h.id}" tabindex="0" role="button" aria-label="Move robber to ${h.resource} ${h.number||'desert'}"/>`;
  html+=placed.filter(([f])=>f.kind==='build'&&f.vertex!=null||f.kind==='robber').map(([f,t])=>{if(f.kind==='robber'){const h=b.hexes[f.hex];return h?`<circle class="placed" data-placed="hex" ${t} cx="${h.x}" cy="${h.y}" r="46"/>`:'';}const v=b.vertices[f.vertex];return `<circle class="placed" data-placed="vertex" ${t} cx="${v.x}" cy="${v.y}" r="${f.piece==='city'?20:17}"/>`;}).join('');
  return html+'</svg>';
}
// Tooltip texts. Names are escaped because they go into attributes.
const nameOf=p=>p<0?'Neutral':escape(state.players[p].name),cap=s=>s[0].toUpperCase()+s.slice(1),pips=n=>6-Math.abs(7-n);
const hexTip=h=>h.resource==='desert'?`Desert: produces nothing.${h.id===state.robber?' The robber waits here.':''}`:`${cap(h.resource)} on ${h.number}: rolled ${pips(h.number)} times in 36 (about ${Math.round(pips(h.number)/36*100)}%).${h.id===state.robber?' The robber blocks it: it produces nothing.':''}`;
const portTip=port=>`${port.resource==='any'?'3:1 port: trade 3 of one resource for 1 of any other':`2:1 ${port.resource} port: trade 2 ${port.resource} for 1 of any resource`}. ${port.vertices.some(v=>state.board.vertices[v].building?.owner===state.me)?'You use this port.':'Build on one of its two spots to use it.'}`;
function buildingTip(v){const {owner,kind}=v.building,made=v.hexes.map(i=>state.board.hexes[i]).filter(h=>h.number).sort((a,b)=>pips(b.number)-pips(a.number)).map(h=>`${h.number} ${h.resource}`);
  return owner<0?'Neutral settlement: blocks this spot and the ones next to it.':`${nameOf(owner)}’s ${kind}${made.length?`: ${kind==='city'?'2 cards':'1 card'} each on ${made.join(', ')}`:''}.`;}
function roadTip(e){const p=state.players[e.owner],on=p.routeEdges?.includes(e.id);return `${nameOf(e.owner)}’s road. Longest route: ${p.route} road${p.route===1?'':'s'}${state.awards.route===e.owner?', holding Longest Route':''} (lit up)${on?'':'; this road is not on it'}.`;}
function awardTip(key){const h=state.awards[key],army=key==='army',n=h===null?0:army?state.players[h].knights:state.players[h].route;
  return `${army?'Largest Army':'Longest Route'}: 2 victory points. ${h===null?(army?'The first player to play 3 Knights takes it.':'The first player with a continuous route of 5 roads takes it.'):`${nameOf(h)} holds it with ${n} ${army?'Knights':'roads'}; ${army?'more Knights':'a longer route'} takes it.`}`;}
function sidebar(){const live=state.phase!=='finished';return `<aside class="sidebar"><div class="section-label"><span class="eyebrow muted">AROUND THE TABLE</span><span class="fine">${state.count} players</span></div>${state.players.map((p,i)=>`<div class="player ${i===state.active&&live?'active':''}" style="--player:${p.color};--mat:${tint(p.color,.84)}"><div class="player-line"><span class="avatar" style="--player:${p.color}">${escape(p.name[0].toUpperCase())}</span><span class="player-name">${escape(p.name)}${i===state.me?' <small class="muted">you</small>':''}</span><span class="points" data-tip="${p.score} victory points">${p.score}</span></div><div class="player-meta"><span class="stat" data-tip="${p.resourceCount} resource cards" aria-label="${p.resourceCount} resource cards">${fan(p.resourceCount,'res')}<b>${p.resourceCount}</b></span><span class="stat" data-tip="${p.cardCount} development cards" aria-label="${p.cardCount} development cards">${fan(p.cardCount,'dev')}<b>${p.cardCount}</b></span><span class="stat" data-tip="${p.knights} knights played" aria-label="${p.knights} knights played">${fan(p.knights,'knight')}<b>${p.knights}</b></span>${stat('route',p.route)}</div>${i===state.active&&live?`<div style="margin-top:8px"><span class="badge turn">${state.count>4?'PLAYER '+state.role:'CURRENT TURN'}</span></div>`:''}${state.awards.route===i||state.awards.army===i?`<div class="mat-awards">${['route','army'].filter(k=>state.awards[k]===i).map(awardTile).join('')}</div>`:''}</div>`).join('')}<div class="section-label supply-label"><span class="eyebrow muted">THE SUPPLY</span></div><div class="bank-summary supply">${R.map(r=>`<div class="stack" data-tip="${state.bank[r]} ${r} left in the supply" style="--terrain:${terrain[r]}">${icon(r,20)}<b>${state.bank[r]}</b></div>`).join('')}<div class="stack deck" data-tip="${state.deckCount} development cards left"><span class="deck-back" aria-hidden="true">◆</span><span class="deck-name">DEV</span><b>${state.deckCount}</b></div></div>${['route','army'].some(k=>state.awards[k]===null)?`<div class="supply-awards">${['route','army'].filter(k=>state.awards[k]===null).map(awardTile).join('')}</div>`:''}<p class="fine" style="margin-top:12px">Your own score includes your hidden Victory Point cards.</p></aside>`;}
// Small emblems for development cards, drawn in the same outlined style as the resource icons.
const EMBLEM={knight:'<path d="M12 3l7 3v6c0 4.5-3.2 7.3-7 8.5C8.2 19.3 5 16.5 5 12V6z" fill="#c9d3dc" stroke="#2a2119" stroke-width="1.6" stroke-linejoin="round"/><path d="M12 7v9M9 10h6" stroke="#2a2119" stroke-width="1.8" stroke-linecap="round"/>',
  roads:'<path d="M4 15 17 5" stroke="#2a2119" stroke-width="5.5" stroke-linecap="round"/><path d="M4 15 17 5" stroke="#c98f5a" stroke-width="3" stroke-linecap="round"/><path d="M7 20 20 10" stroke="#2a2119" stroke-width="5.5" stroke-linecap="round"/><path d="M7 20 20 10" stroke="#dcaa72" stroke-width="3" stroke-linecap="round"/>',
  invention:'<circle cx="12" cy="10" r="6" fill="#f6d77a" stroke="#2a2119" stroke-width="1.6"/><path d="M9.5 16h5v3.5h-5z" fill="#9aa3a8" stroke="#2a2119" stroke-width="1.4" stroke-linejoin="round"/><path d="M12 6.5v3.5M10 10h4" stroke="#b07d1e" stroke-width="1.5" stroke-linecap="round"/>',
  monopoly:'<ellipse cx="12" cy="17" rx="7" ry="2.6" fill="#d9a63c" stroke="#2a2119" stroke-width="1.4"/><ellipse cx="12" cy="13" rx="7" ry="2.6" fill="#e8bb4c" stroke="#2a2119" stroke-width="1.4"/><ellipse cx="12" cy="9" rx="7" ry="2.6" fill="#f3cf63" stroke="#2a2119" stroke-width="1.4"/>',
  vp:'<path d="M12 3l2.6 5.6 6.1.7-4.5 4.1 1.2 6L12 16.4 6.6 19.4l1.2-6L3.3 9.3l6.1-.7z" fill="#f2c94c" stroke="#2a2119" stroke-width="1.5" stroke-linejoin="round"/>'};
// Your hand: one card per resource, stacked when you hold several, fanned slightly like cards held at the table.
function hand(){const me=state.players[state.me],active=state.me===state.active,playable=c=>active&&!me.played&&c.bought!==state.turn&&c.type!=='vp'&&['preRoll','action'].includes(state.phase);
  return `<section class="hand"><div class="hand-top"><span class="eyebrow">YOUR HAND</span><span class="fine">${me.resourceCount} resource card${me.resourceCount===1?'':'s'} · only you can see them</span></div><div class="hand-row"><div class="hand-cards">${R.map((r,i)=>{const n=me.hand[r];return `<div class="resource-card${n?'':' empty'}${n>1?' stacked':''}${n>2?' deep':''}" style="--terrain:${terrain[r]};--tilt:${(i-2)*3}deg;--drop:${Math.abs(i-2)*4}px" data-tip="${n} ${r}. The supply gives you any 1 resource for ${state.ratios?.[r]??4} ${r}."><div class="resource-art">${icon(r,36)}</div><span>${r.toUpperCase()}</span><b>${n}</b></div>`;}).join('')}</div>${me.cards.length?`<div class="dev-cards">${devStacks(me,playable)}</div>`:''}${buildBar()}</div></section>`;}
// Build bar beside the hand: each piece with its cost and how many are left; tap one, then a highlighted spot on the board.
const BUILD=[['road','Road',{wood:1,brick:1}],['settlement','Settlement',{wood:1,brick:1,wool:1,wheat:1}],['city','City',{ore:3,wheat:2}],['buyCard','Dev card',{ore:1,wool:1,wheat:1}]];
// Same development cards stack into one card with a count; clicking plays a playable one, so cards bought this turn wait.
const DEV_HELP={knight:'Move the robber and steal 1 resource from a player next to it. Counts toward Largest Army.',roads:'Build 2 roads for free.',invention:'Take any 2 resources from the supply.',monopoly:'Name a resource: every other player gives you all of theirs.',vp:'1 victory point, counted automatically and hidden from others until the game ends.'};
function devStacks(me,playable){return Object.keys(names).map(type=>{const cards=me.cards.filter(c=>c.type===type);if(!cards.length)return '';const ready=cards.find(playable),fresh=cards.filter(c=>c.bought===state.turn).length;
  const why=type==='vp'?'Counts automatically':ready?`Click to play one`:fresh===cards.length?'Bought this turn: playable from your next turn':'Play on your turn, one card per turn';
  return `<button class="dev-card ${type}" data-card="${(ready||cards[0]).id}" data-type="${type}" ${ready?'':'disabled'} data-tip="${names[type]}: ${DEV_HELP[type]} ${why}."><svg viewBox="0 0 24 24" aria-hidden="true">${EMBLEM[type]}</svg><span>${names[type]}</span>${fresh?`<small>${fresh>1?fresh+' ':''}new</small>`:''}${cards.length>1?`<b>${cards.length}</b>`:''}</button>`;}).join('');}
function buildPiece(type,color){if(type==='road')return `<svg viewBox="-16 -14 32 28" aria-hidden="true">${roadBar(-11,8,11,-8,color)}</svg>`;if(type==='buyCard')return `<svg viewBox="-16 -14 32 28" aria-hidden="true"><rect x="-8" y="-12" width="16" height="23" rx="2.5" fill="#2f4d48" stroke="#1c3330" stroke-width="1.4"/><path d="M0 -5l4 5-4 5-4-5z" fill="#f2c94c"/></svg>`;return `<svg viewBox="-16 -20 32 32" aria-hidden="true">${piece(type,color)}</svg>`;}
function buildBar(){const me=state.players[state.me],active=state.me===state.active,open=active&&state.phase==='action',mine=k=>state.board.vertices.filter(v=>v.building?.owner===state.me&&v.building.kind===k).length;
  const left={road:15-state.board.edges.filter(e=>e.owner===state.me).length,settlement:5-mine('settlement'),city:4-mine('city'),buyCard:state.deckCount},spots={road:state.legal.roads.length,settlement:state.legal.settlements.length,city:state.legal.cities.length,buyCard:1};
  return `<div class="build-bar" data-ui="build-bar"><span class="eyebrow">BUILD</span><div class="build-buttons">${BUILD.map(([type,title,cost])=>{const why=!open?(active?'Finish the current step first':'Build on your turn'):!left[type]?'None left':!Object.entries(cost).every(([r,n])=>me.hand[r]>=n)?'Not enough resources':!spots[type]?'No legal spot on the board':'';
    // Each cost card is marked as in hand or missing, so you can see what to trade for even off-turn.
    const missing=Object.entries(cost).filter(([r,n])=>me.hand[r]<n).map(([r,n])=>`${n-me.hand[r]} ${r}`).join(', ');
    return `<button class="build${mode===type?' selected':''}" ${type==='buyCard'?'data-command':'data-mode'}="${type}" ${why?'disabled':''} data-tip="${title}${why?': '+why:''}${missing?` (missing ${missing})`:''}. ${left[type]} left."><span class="build-piece">${buildPiece(type,me.color)}</span><span class="build-name">${title}</span><span class="build-cost">${Object.entries(cost).flatMap(([r,n])=>Array.from({length:n},(_,k)=>`<i class="cost ${k<me.hand[r]?'have':'miss'}" data-res="${r}">${icon(r,13)}</i>`)).join('')}</span><b class="build-left" aria-label="${left[type]} left">${left[type]}</b></button>`;}).join('')}</div></div>`;}
// Card pickers replace number inputs: tap a card to add one, tap − to take one back. Hidden inputs carry the counts.
function picker(prefix,limit,start={}){return `<div class="picker">${R.map(r=>{const max=limit?limit[r]:99;return `<div class="pick${max?'':' none'}" style="--terrain:${terrain[r]}"><button type="button" class="pick-card" data-pick="${prefix}-${r}" data-step="1" ${max?'':'disabled'} aria-label="Add one ${r}" data-tip="${limit?`${max} available`:`Add ${r}`}"><span class="pick-art">${icon(r,24)}</span><span class="pick-name">${r}</span><b class="pick-count">0</b></button><button type="button" class="pick-less" data-pick="${prefix}-${r}" data-step="-1" aria-label="Take back one ${r}">−</button><input type="hidden" name="${prefix}-${r}" value="${Math.min(start[r]||0,max)}" data-max="${max}"></div>`;}).join('')}</div>`;}
// Redraws picker counts, running totals and single-choice highlights from the hidden inputs (after a tap or a live re-render).
function syncPickers(){for(const input of app.querySelectorAll('.picker input')){const n=Number(input.value)||0,box=input.closest('.pick');box.querySelector('.pick-count').textContent=n;box.classList.toggle('picked',n>0);box.querySelector('.pick-less').disabled=n<=0;}
  for(const total of app.querySelectorAll('[data-total]')){const sum=[...total.closest('form').querySelectorAll('.picker input')].reduce((s,i)=>s+(Number(i.value)||0),0);total.textContent=`${sum} of ${total.dataset.total} chosen`;}
  for(const group of app.querySelectorAll('[data-choice]')){const value=group.querySelector('input').value;for(const b of group.querySelectorAll('[data-choose]'))b.classList.toggle('chosen',b.dataset.choose===value);}}
function scoreboard(){const rows=state.players.map((p,i)=>{const mine=state.board.vertices.filter(v=>v.building?.owner===i),built=mine.reduce((n,v)=>n+(v.building.kind==='city'?2:1),0),awards=(state.awards.route===i?2:0)+(state.awards.army===i?2:0),vp=(p.cards||[]).filter(c=>c.type==='vp').length;return {p,i,built,awards,vp};}).sort((a,b)=>b.p.score-a.p.score);
  return `<table class="scoreboard"><thead><tr><th>Player</th><th data-tip="Settlements and cities">Built</th><th data-tip="Longest Route and Largest Army">Awards</th><th data-tip="Victory Point cards">Cards</th><th>Total</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.i===state.winner?'won':''}"><td><span class="dot" style="--player:${r.p.color}"></span>${escape(r.p.name)}</td><td>${r.built}</td><td>${r.awards}</td><td>${r.vp}</td><td><b>${r.p.score}</b></td></tr>`).join('')}</tbody></table>`;}
// Trading floats over the board's top-right corner: Players and Supply tabs for the current player, and every open offer.
// It opens by itself for offers someone has not dismissed; closing it hides the current offers until a new one arrives.
function tradePanel(){if(state.phase!=='action')return '';const me=state.players[state.me],active=state.me===state.active,tabs=[...(active&&state.role===1?[['trade','Players','handshake']]:[]),...(active?[['bank','Supply','bank']]:[])];
  const base=counter&&state.offers.find(o=>o.id===counter);if(mode==='trade'&&!(active&&state.role===1)&&!base)mode='';
  const tabHtml=tabs.map(([m,label,k])=>`<button class="tab${mode===m?' selected':''}" data-mode="${m}">${ui(k)} ${label}</button>`).join('');
  if(!(mode==='trade'||mode==='bank'||state.offers.some(o=>!dismissed.has(o.id))))return tabs.length||state.offers.length?`<div class="trade-launcher" data-ui="trade-launcher"><span class="eyebrow">TRADE</span>${tabHtml}${state.offers.length?`<button class="tab" data-ui="trade-show">Offers <b>${state.offers.length}</b></button>`:''}</div>`:'';
  const form=mode==='bank'?`<form id="bank" class="panel"><h3>Trade with the supply</h3><p class="fine">Give</p><div class="choice" data-choice="give">${R.map(r=>`<button type="button" class="choice-card" data-choose="${r}" data-ratio="${r}" ${me.hand[r]>=state.ratios[r]?'':'disabled'} style="--terrain:${terrain[r]}" data-tip="Give ${state.ratios[r]} ${r}">${icon(r,24)}<span class="ratio">${state.ratios[r]}:1</span></button>`).join('')}<input type="hidden" name="give" value=""></div><p class="fine">Receive 1</p><div class="choice" data-choice="want">${R.map(r=>`<button type="button" class="choice-card" data-choose="${r}" ${state.bank[r]?'':'disabled'} style="--terrain:${terrain[r]}" data-tip="Receive 1 ${r}">${icon(r,24)}<span>${r}</span></button>`).join('')}<input type="hidden" name="want" value=""></div><button class="primary wide">Trade</button></form>`:mode==='trade'?`<form id="trade" class="panel"><h3>${base?'My counteroffer: I give':'I offer'}</h3>${picker('give',me.hand,base?.want)}<h3 style="margin-top:15px">I want</h3>${picker('want',null,base?.give)}<input type="hidden" name="counterTo" value="${base?escape(base.id):''}"><button class="primary wide">${base?'Send counteroffer':'Send offer'}</button><p class="fine" style="margin:10px 0 0">${base?`Only ${escape(state.players[state.active].name)} can accept it.`:'Everyone can accept or counter; you choose who to trade with.'}</p></form>`:'';
  return `<aside class="trade-panel" data-ui="trade-panel" aria-label="Trading"><div class="trade-head"><span class="eyebrow">TRADE</span><div class="trade-tabs">${tabHtml}</div><button class="trade-close" data-ui="trade-close" aria-label="Close trading">${ui('close')}</button></div>${form}${state.offers.length?`<div class="trade-table">${state.offers.map(offerHtml).join('')}</div>`:''}${!form&&!state.offers.length?'<p class="fine">No offers on the table.</p>':''}</aside>`;}
// One offer on the table, with the answers open to whoever is looking: the current player confirms one of the players who accepted
// or settles a counteroffer; the others accept, withdraw, decline or counter.
function offerHtml(o){const me=state.me,active=me===state.active,mine=o.from===me,isCounter=o.from!==state.active,accepted=o.accepted??[],declined=o.declined??[],who=i=>escape(state.players[i].name);let actions='';
  if(isCounter)actions=active?`<button class="gold small" data-accept="${escape(o.id)}">Accept counteroffer</button> <button class="ghost small" data-decline="${escape(o.id)}">Decline</button>`:mine?`<button class="ghost small" data-cancel="${escape(o.id)}">Withdraw</button>`:'';
  else if(mine)actions=`${accepted.map(i=>`<button class="gold small" data-confirm="${escape(o.id)}" data-player="${i}">Trade with ${who(i)}</button> `).join('')}<button class="ghost small" data-cancel="${escape(o.id)}">Cancel</button>`;
  else if(o.to===null||o.to===me){const can=R.every(r=>state.players[me].hand[r]>=o.want[r]);actions=accepted.includes(me)?`<span class="badge ready">Accepted ${ui('check')}</span> <button class="ghost small" data-decline="${escape(o.id)}">Withdraw</button>`:`<button class="gold small" data-accept="${escape(o.id)}" ${can?'':'disabled data-tip="You do not have the requested resources"'}>Accept</button> ${declined.includes(me)?'':`<button class="ghost small" data-decline="${escape(o.id)}">Decline</button> `}<button class="ghost small" data-counter="${escape(o.id)}">Counter</button>`;}
  const answers=isCounter?'':[accepted.length?`Accepted: ${accepted.map(who).join(', ')}`:'',declined.length?`Declined: ${declined.map(who).join(', ')}`:''].filter(Boolean).join(' · ');
  const fresh=!seenOffers.has(o.id);seenOffers.add(o.id);return `<div class="offer${fresh?' fresh':''}" style="--player:${state.players[o.from].color}"><div class="offer-who"><span class="dot"></span><b>${who(o.from)}</b> ${isCounter?'counters':'offers'} </div><div class="offer-cards">${miniCards(o.give)}</div><div class="offer-for">for</div><div class="offer-cards">${miniCards(o.want)}</div>${answers?`<p class="fine offer-answers">${answers}</p>`:''}<div class="offer-actions">${actions}</div></div>`;}
// History lines. Each player's own secrets (a stolen resource, a bought card) arrive only in their own view.
const resList=b=>R.filter(r=>b?.[r]).map(r=>`<span class="log-res" data-tip="${b[r]} ${r}">${b[r]}${icon(r,14)}<span class="sr">${r}</span></span>`).join(' ')||'nothing';
const AWARD={route:'Longest Route',army:'Largest Army'};
function story(e){if(e.text)return escape(e.text);const P=i=>i===null||i===undefined?'nobody':`<b class="who"><i style="--player:${state.players[i].color}"></i>${escape(state.players[i].name)}</b>`,who=P(e.p),hexName=h=>{const x=state.board.hexes[h];return `${x.number?x.number+' ':''}${x.resource}`;};
  switch(e.kind){
    case 'first':return `${who} won the starting roll.`;
    case 'gain':return `${who} received ${resList(e.res)}.`;
    case 'build':return `${who} built a ${e.piece}${e.free?' (free)':''}${e.gain?` and received ${resList(e.gain)}`:''}.`;
    case 'roll':{const total=e.dice[0]+e.dice[1];if(total===7)return `${who} rolled <b>7</b>.`;const by=new Map();for(const g of e.gains){const b=by.get(g.p)??{};b[g.r]=(b[g.r]??0)+g.n;by.set(g.p,b);}
      return `${who} rolled <b>${total}</b>.${by.size?[...by].map(([p,b])=>`<span class="log-sub">${P(p)} +${resList(b)}</span>`).join(''):'<span class="log-sub">Nobody produced.</span>'}${e.blocked!==null&&e.blocked!==undefined?`<span class="log-sub">The robber blocked the ${hexName(e.blocked)}.</span>`:''}${e.short?.length?`<span class="log-sub">The supply ran short of ${e.short.join(', ')}.</span>`:''}`;}
    case 'discard':return `${who} discarded ${resList(e.res)}.`;
    case 'robber':return `${who} moved the robber to the ${hexName(e.hex)}.`;
    case 'steal':return `${who} stole ${e.secret?resList({[e.secret.r]:1}):'a resource'} from ${P(e.from)}.`;
    case 'buy':return `${who} bought a development card${e.secret?` (${names[e.secret.card]})`:''}.`;
    case 'play':return `${who} played <span class="log-card" data-tip="${DEV_HELP[e.card]}">${names[e.card]}</span>.`;
    case 'monopoly':return `${who} claimed every ${e.r}: ${e.from.length?e.from.map(f=>`${f.n} from ${P(f.p)}`).join(', '):'nobody had any'}.`;
    case 'invention':return `${who} took ${resList(e.res)} from the supply.`;
    case 'offer':return `${who} ${e.counter?'countered with':'offered'} ${resList(e.give)} for ${resList(e.want)}.`;
    case 'respond':return `${who} ${e.answer==='accept'?'accepted':e.answer==='withdraw'?'withdrew from':'declined'} ${P(e.from)}’s offer.`;
    case 'cancel':return e.p===e.from?`${who} withdrew an offer.`:`${who} removed ${P(e.from)}’s offer.`;
    case 'trade':return `${who} traded with ${P(e.with)}: gave ${resList(e.give)}, got ${resList(e.want)}.`;
    case 'bank':return `${who} traded ${resList(e.give)} with the supply for ${resList(e.want)}.`;
    case 'award':return e.p===null?`${P(e.from)} lost ${AWARD[e.award]}.`:`${who} took ${AWARD[e.award]}${e.from!==null?` from ${P(e.from)}`:''}.`;
    case 'end':return `${who} ended ${state.count>4?'their phase':'their turn'}.`;
    case 'win':return `${who} wins with ${e.score} points!`;
  }return escape(e.kind);}
function controls(){const me=state.players[state.me],active=state.active===state.me,phase=state.phase;const instructions={setupSettlement:'Choose a highlighted intersection for your settlement.',setupRoad:'Place a road next to your new settlement.',preRoll:active?'Tap the glowing dice on the board to roll, or play a development card first.':'Waiting for the dice.',action:state.role===2?'Build, use ports, or play a card. No player trades.':'Trade with friends. Build your next move.',discard:'Players with more than 7 cards must discard half.',robber:'Choose a different hex for the robber.',steal:'Choose a player to steal one resource from.',freeRoads:'Place your free roads on highlighted edges.',invention:'Choose two resources from the supply.',monopoly:'Choose a resource to collect from everyone.',finished:'An island well settled.'};
  // Discards are simultaneous, so the turn card speaks to whoever still owes cards rather than to the roller.
  const owed=phase==='discard'?state.players.map((p,i)=>state.discards[i]?p.name:null).filter(Boolean):[];
  function turnText(){if(phase==='discard'){const mine=state.discards[state.me];return mine?`<h2>Discard ${mine} cards.</h2><p>A 7 was rolled and you hold more than 7 cards. Return half to the supply below.</p>`:`<h2>Waiting for discards.</h2><p>${escape(owed.join(', '))} must return cards before ${active?'you move':escape(state.players[state.active].name)+' moves'} the robber.</p>`;}return `<h2>${active?'Your move.':escape(state.players[state.active].name)+'’s move.'}</h2><p>${instructions[phase]}</p>`;}
  let html=`<aside class="control-sidebar">${phase==='finished'?(victoryClosed?'':'<p class="waiting">The game is over.</p>')+(!victoryClosed?'':`<div class="winner"><span class="eyebrow">THE ISLAND HAS A WINNER</span><h2>${escape(state.players[state.winner].name)} wins!</h2><p class="fine">${state.players[state.winner].score} victory points. Every hidden card is now revealed.</p>${scoreboard()}${state.me===0?'<button class="primary wide" data-command="rematch">Play again '+ui('arrow')+'</button>':'<p class="fine" style="margin:12px 0 0">The host can start a rematch.</p>'}</div>`):`<div class="turn-card" style="--player:${state.players[state.active].color}"><span class="seal" aria-hidden="true">${escape(state.players[state.active].name[0].toUpperCase())}</span><span class="eyebrow">${phase.startsWith('setup')?'FOUNDATIONS · ROUND '+(state.setupIndex>=state.count?2:1):'TURN '+state.turn+(state.count>4?' · PAIRED PLAYER '+state.role:'')}</span>${turnText()}${state.dice?`<p class="rolled">Rolled <b>${state.dice[0]+state.dice[1]}</b></p>`:''}</div>`}`;
  if(phase==='discard'&&state.discards[state.me])html+=`<form class="panel" id="discard"><h3>Return ${state.discards[state.me]} resources</h3><p class="fine">Tap cards to put them back in the supply.</p>${picker('discard',me.hand)}<p class="fine pick-total" data-total="${state.discards[state.me]}"></p><button class="primary wide">Confirm discard</button></form>`;
  if(active&&phase==='invention')html+=`<form class="panel" id="invention"><h3>Take 2 available resources</h3>${picker('take',state.bank)}<p class="fine pick-total" data-total="2"></p><button class="primary wide">Collect resources</button></form>`;
  if(active&&phase==='monopoly')html+=`<div class="panel"><h3>Collect all of one resource</h3><div class="choice">${R.map(r=>`<button class="choice-card" data-monopoly="${r}" style="--terrain:${terrain[r]}">${icon(r,24)}<span>${r}</span></button>`).join('')}</div></div>`;
  if(active&&phase==='steal')html+=`<div class="panel"><h3>Choose a player</h3>${state.victims.map(p=>`<button class="ghost wide" data-victim="${p}">${escape(state.players[p].name)} · ${state.players[p].resourceCount} cards</button>`).join('')}</div>`;
  if(active&&phase==='action')html+=`${mode&&['road','settlement','city'].includes(mode)?`<p class="fine build-hint">Choose a highlighted ${mode==='road'?'edge':'intersection'} on the island. Esc cancels.</p>`:''}<button class="primary wide" data-command="end">End ${state.count>4?'my phase':'turn'} ${ui('arrow')}</button>`;
  if(!active&&!['finished','discard'].includes(phase))html+=`<p class="waiting" style="margin-top:18px">${phase==='action'&&state.role===1?'Answer the current player’s offers while you wait.':'The board updates live. Your next move will appear here.'}</p>`;
  html+=`<section class="log"><div class="section-label"><span class="eyebrow muted">THE STORY SO FAR</span><span class="fine">LIVE</span></div><div class="log-list">${state.events.toReversed().slice(0,60).map(e=>`<div class="log-item">${story(e)}</div>`).join('')||'<p class="fine">Every great island starts with two settlements.</p>'}</div></section></aside>`;return html;
}
// The dice on the table are the roll button: big and glowing when it is your roll. Every new roll tumbles on every screen
// and shows its total for a moment.
function diceHtml(){if(['setupSettlement','setupRoad'].includes(state.phase))return '';const mine=state.active===state.me&&state.phase==='preRoll',d=state.dice??[5,2];if(!state.dice&&!mine)return '';
  const roll=effect('roll',2600),faces=`<span class="die-wrap">${die(d[0],-8)}</span><span class="die-wrap">${die(d[1],11)}</span>`;
  if(mine)return `<button class="table-dice roll-me" data-command="roll" aria-label="Roll the dice"><span class="dice-pair">${faces}</span><span class="roll-hint">${ui('dice')} Roll the dice</span></button>`;
  const last=state.events.findLast(e=>e.kind==='roll'),tip=last?`${nameOf(last.p)} rolled ${d[0]+d[1]}.`:'';
  return `<div class="table-dice${roll?' tumbling':''}"${roll?` style="--t:-${since(roll)}ms"`:''} aria-label="Last roll ${d[0]+d[1]}" data-tip="${tip}">${roll?`<span class="roll-total">${d[0]+d[1]}</span>`:''}<span class="dice-pair">${faces}</span></div>`;}
function game(){return `${header()}<main class="game-layout">${sidebar()}<section class="board-column"><div class="board-wrap">${tradePanel()}<div class="table-line">${state.setup==='fixed'?'Fixed':'Variable'} island · ${state.map==='extended'?'Extended map':'Base map'} · First to 10 points</div>${board()}${diceHtml()}</div>${hand()}</section>${controls()}</main>`;}
// The end of the game takes the whole screen: the winner in their colour, confetti, the final scores, and a way back to the board.
const CONFETTI=Array.from({length:70},(_,i)=>({x:(i*53)%100,d:((i*37)%60)/10,len:3.2+((i*17)%25)/10,w:6+(i*7)%7,turn:(i%2?1:-1)*(360+(i*29)%360),c:i%5}));
function victoryHtml(){if(state?.phase!=='finished'){victoryClosed=false;victoryAt=0;return '';}if(victoryClosed)return '';victoryAt||=performance.now();const w=state.players[state.winner],colors=[w.color,'#f2c94c','#fbefd2',tint(w.color,.45),'#e07a5f'],t=Math.round(performance.now()-victoryAt);
  return `<div class="victory" data-ui="victory" role="dialog" aria-modal="true" aria-label="${escape(w.name)} wins" style="--player:${w.color};--t:-${t}ms"><div class="confetti" aria-hidden="true">${CONFETTI.map(c=>`<i style="left:${c.x}%;width:${c.w}px;background:${colors[c.c]};animation-delay:calc(var(--t) + ${c.d}s);animation-duration:${c.len}s;--turn:${c.turn}deg"></i>`).join('')}</div><section class="victory-card winner"><span class="trophy">${ui('trophy')}</span><span class="eyebrow">THE ISLAND HAS A WINNER</span><h1><span class="victory-name">${escape(w.name)}</span> wins!</h1><p class="victory-points">${w.score} victory points${state.winner===state.me?' — well played!':''}</p>${scoreboard()}<div class="victory-actions"><button class="ghost" data-ui="victory-close">View the board</button>${state.me===0?'<button class="gold" data-command="rematch">Play again '+ui('arrow')+'</button>':'<p class="fine">The host can start a rematch.</p>'}</div></section></div>`;}
function modalHtml(){if(!modal)return '';let content='';if(modal==='help'||modal==='costs')content=`<dl class="help"><dt>Settle in</dt><dd>Place a settlement and road, then a second pair in reverse player order. Your second settlement provides starting resources. Fixed islands place your starting pieces for you.</dd><dt>A turn on the island</dt><dd>Roll two dice. Settlements beside matching hexes collect 1 resource; cities collect 2. Trade and build in any order, then end your turn.</dd><dt>Building costs</dt><dd>Road: 1 wood + 1 brick<br>Settlement: 1 wood + 1 brick + 1 wool + 1 wheat<br>City: 3 ore + 2 wheat<br>Development: 1 ore + 1 wool + 1 wheat</dd><dt>Space to grow</dt><dd>New roads connect to your network. New settlements connect to your road and stay at least two edges from all buildings. Cities replace your settlements.</dd><dt>Trading</dt><dd>Exchange 4 matching resources for 1 at the supply. Ports improve this to 3:1 or 2:1. On your turn, offer a trade to everyone; the others accept, decline or counter, and you choose who to trade with. Gifts and matching resources on both sides are not allowed.</dd><dt>When a seven appears</dt><dd>Players with more than 7 resources discard half, rounded down. The roller moves the robber to a new hex and steals a random resource (automatically when only one player is there to rob). That hex stops producing.</dd><dt>Development cards</dt><dd>Play one per turn before rolling or during actions, never one bought during that same turn. Knights move the robber. Road Building gives two roads. Invention takes two resources. Monopoly takes everyone's cards of one resource. Victory Point cards stay hidden until you win.</dd><dt>Paired turns · 5–6 players</dt><dd>Player 1 rolls and takes actions. The player three seats clockwise then takes an action phase without rolling or trading with other players. Supply trades and development cards are allowed. Either can win during their own portion.</dd><dt>Ten points wins</dt><dd>Settlements are 1 point, cities 2. Longest Route (5+ roads) and Largest Army (3+ Knights) are worth 2 each. Hidden Victory Point cards count on your turn.</dd><dt>Digital table conventions</dt><dd>Starting roll ties are rerolled. Road Building places as many roads as legally possible, up to two. A route may revisit intersections but never an edge. Invention takes all available resources if fewer than two remain. See RULES.md for implementation notes about board presets.</dd><dt>Credits</dt><dd>Interface icons from <a href="https://fontawesome.com" target="_blank" rel="noopener">Font Awesome Free</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Board, pieces and resource art are original.</dd></dl>`;
  if(modal==='seat')content=`<p style="margin-top:20px;font-size:13px">Keep this key private: it grants access to your seat and cards. Paste it on another device using “Recover a seat” below.</p><input readonly value="${session.room}:${session.token}" aria-label="Private seat recovery key"><button class="primary wide" data-ui="copy-seat">Copy private recovery key</button>`;
  if(modal==='recover')content='<form id="recover"><label>PRIVATE SEAT RECOVERY KEY</label><input name="key" required placeholder="room:private-key"><button class="primary wide">Recover my seat</button></form>';
  return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${modal==='seat'?'Seat recovery':'Game guide'}"><div class="modal-header"><h2>${modal==='seat'||modal==='recover'?'Your saved seat.':'A little field guide.'}</h2><button data-ui="close" aria-label="Close dialog">${ui('close')}</button></div>${content}${modal==='help'?'<button class="ghost wide" data-ui="recover">Recover a seat on this device</button>':''}</section></div>`;
}
// Flying cards live in their own layer outside #app, so redraws from the live stream never cut an animation short.
// Your own cards fly to your hand; everyone else's to their place around the table. A stolen card is face-down unless it is yours.
const fxLayer=()=>document.getElementById('fx')??document.body.appendChild(Object.assign(document.createElement('div'),{id:'fx'}));
const seatOf=p=>p===state.me?document.querySelector('.hand-cards'):document.querySelectorAll('.sidebar .player')[p];
const cardOf=(p,r)=>p===state.me&&r?document.querySelectorAll('.hand-cards .resource-card')[R.indexOf(r)]:seatOf(p);
function fly(html,from,to,delay,land){setTimeout(()=>{const a=from()?.getBoundingClientRect(),b=to()?.getBoundingClientRect();if(!a?.width||!b?.width)return;const el=Object.assign(document.createElement('div'),{className:'fly',innerHTML:html});fxLayer().append(el);
  const x0=a.left+a.width/2,y0=a.top+a.height/2,x1=b.left+b.width/2,y1=b.top+b.height/2,lift=Math.min(140,Math.hypot(x1-x0,y1-y0)/3);
  el.animate([{transform:`translate(${x0}px,${y0}px) scale(.5)`,opacity:0},{transform:`translate(${x0}px,${y0-26}px) scale(1.3)`,opacity:1,offset:.2},{transform:`translate(${(x0+x1)/2}px,${Math.min(y0,y1)-lift}px) scale(1.1)`,opacity:1,offset:.55},{transform:`translate(${x1}px,${y1}px) scale(.7)`,opacity:.85}],{duration:1050,easing:'ease-in-out',fill:'both'}).finished.then(()=>{el.remove();land?.();to()?.animate({filter:['brightness(1)','brightness(1.45)','brightness(1)']},{duration:380});});},delay);}
// Each new history entry plays once: its sound for everyone at the table (a few only for the player concerned), and its flying cards.
function playEffects(){if(!state?.board)return;const still=matchMedia('(prefers-reduced-motion: reduce)').matches,me=state.me;for(const f of effects){if(f.played)continue;f.played=true;
  const build={road:'road',settlement:'settlement',city:'city'}[f.piece];
  ({roll:()=>{cue('roll');if(f.dice[0]+f.dice[1]===7&&state.discards?.[me])cue('warn',0);},robber:()=>cue('robber'),steal:()=>{cue('steal');if(f.from===me)setTimeout(()=>cue('sour'),300);},build:()=>build&&cue(build),buy:()=>cue('flip'),play:()=>cue('play'),monopoly:()=>cue('coins'),invention:()=>cue('sparkle'),discard:()=>cue('flip'),trade:()=>cue('clink'),bank:()=>cue('clink'),award:()=>f.p!==null&&cue('sting'),end:()=>cue('end'),win:()=>cue('fanfare'),
    offer:()=>{if(f.p!==me&&(f.counter?me===state.active:me!==state.active))cue('offer');},respond:()=>{if(f.from===me&&f.answer==='accept')cue('tick');}})[f.kind]?.();
  if(f.gains)f.gains.forEach((g,i)=>{for(let k=0;k<Math.min(g.n,3);k++){const at=(f.kind==='roll'?800:150)+i*150+k*110;if(still)setTimeout(()=>cue('pop',g.r),at+900);else fly(icon(g.r,30),()=>document.querySelector(`[data-tile="${g.hex}"]`),()=>cardOf(g.p,g.r),at,()=>cue('pop',g.r));}});
  if(f.kind==='steal'&&!still){const r=f.secret?.r;fly(r?icon(r,30):'<span class="fly-back"></span>',()=>cardOf(f.from,r),()=>cardOf(f.p,r),250);}}
  // Your turn starting is a change of state rather than an entry: chime once per turn, never for the state a page first loads.
  const turnKey=`${state.turn}:${state.setupIndex??''}:${state.active}:${state.role}`,mine=state.active===me&&(['preRoll','setupSettlement'].includes(state.phase)||state.phase==='action'&&state.role===2);
  if(turnCue===null)turnCue=turnKey;else if(mine&&turnCue!==turnKey){turnCue=turnKey;cue('turn');}}
function render(preserve=false){if(state?.board)noticeEvents();if(state?.phase==='lobby')turnCue='lobby';const fields=preserve?[...app.querySelectorAll('form input,form select')].map(e=>({form:e.form.id,name:e.name,value:e.value,focused:document.activeElement===e})):[];app.innerHTML=(state?(state.phase==='lobby'?lobby():game()):home())+victoryHtml()+modalHtml();for(const f of fields){const el=document.getElementById(f.form)?.elements.namedItem(f.name);if(el){el.value=f.value;if(f.focused)el.focus();}}syncPickers();playEffects();retip();}
// The clipboard API needs a secure context, which plain http LAN addresses are not; fall back to a selected textarea.
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{const area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','');area.style.cssText='position:fixed;opacity:0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?message:`Copy this link: ${text}`);}}
// Tooltips: anything with data-tip explains itself after a short hover, or a long press on touch. The #tip layer lives outside #app,
// so redraws don't remove it; after one, the tip and the route highlight are re-attached to whatever is under the pointer.
let tipFor=null,tipTimer=0,tipAt=null,pressed=false;
function tipLayer(){return document.getElementById('tip')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'tip',role:'tooltip'}));}
function showTip(el){const tip=tipLayer();tipFor=el;tip.textContent=el.dataset.tip;tip.classList.add('visible');const r=el.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let y=r.top-h-8;if(y<6)y=r.bottom+8;tip.style.transform=`translate(${Math.round(Math.min(Math.max(6,r.left+r.width/2-w/2),innerWidth-w-6))}px,${Math.round(Math.min(y,innerHeight-h-6))}px)`;}
function hideTip(){clearTimeout(tipTimer);tipFor=null;document.getElementById('tip')?.classList.remove('visible');}
// Hovering a road lights up that player's longest route.
function lightRoute(el){const svg=document.querySelector('svg.board');if(!svg)return;svg.querySelectorAll('.route-lit').forEach(r=>r.classList.remove('route-lit'));const road=el?.closest?.('[data-road]'),edges=road&&state?.players[+road.dataset.owner]?.routeEdges;svg.classList.toggle('route-mode',!!edges?.length);for(const id of edges||[])svg.querySelector(`[data-road="${id}"]`)?.classList.add('route-lit');}
function hover(el){lightRoute(el);if(el===tipFor)return;clearTimeout(tipTimer);if(!el?.dataset.tip)return hideTip();tipTimer=setTimeout(()=>showTip(el),tipFor?0:350);}
function retip(){if(!tipAt)return;const el=document.elementFromPoint(...tipAt)?.closest('[data-tip]');lightRoute(el);if(tipFor&&!tipFor.isConnected){tipFor=null;if(el)showTip(el);else hideTip();}}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;tipAt=[e.clientX,e.clientY];hover(e.target.closest?.('[data-tip]'));});
document.documentElement.addEventListener('pointerleave',()=>{tipAt=null;hover(null);});
document.addEventListener('pointerdown',e=>{hideTip();if(e.pointerType!=='touch')return;const el=e.target.closest?.('[data-tip]');if(el)tipTimer=setTimeout(()=>{pressed=true;lightRoute(el);showTip(el);},450);});
document.addEventListener('pointerup',()=>{clearTimeout(tipTimer);if(pressed)setTimeout(()=>{hideTip();lightRoute(null);},1800);});
// A long press only shows the tip; it must not also click what is under the finger.
document.addEventListener('click',e=>{if(pressed){pressed=false;e.preventDefault();e.stopPropagation();}},true);
addEventListener('scroll',hideTip,true);
let inviteOrigin=null;fetch('/api/config').then(r=>r.json()).then(c=>{inviteOrigin=c.inviteOrigin;}).catch(()=>{});
function invite(){const local=/^(localhost|127\.|\[::1\])/.test(location.hostname);if(local&&!inviteOrigin)return copy(`${location.origin}/?room=${session.room}`,'Copied, but this link only works on this computer. Set PUBLIC_ORIGIN to your network address so friends can join.');copy(`${inviteOrigin||location.origin}/?room=${session.room}`,'Invitation copied. Send it to your friends.');}
document.addEventListener('click',async e=>{
  const el=e.target.closest('button,[data-edge],[data-vertex],[data-hex]');if(!el||el.disabled)return;
  if(el.dataset.ui){const action=el.dataset.ui;if(action.startsWith('tab-')){tab=action.slice(4);render();}if(action==='help'||action==='costs'||action==='seat'||action==='recover'){modal=action;render();}if(action==='close'){modal='';render();}if(action==='invite')invite();if(action==='mute'){muted=!muted;try{localStorage.setItem('island-muted',muted?'1':'0');}catch{}render();}if(action==='victory-close'){victoryClosed=true;render();}if(action==='trade-close'){mode='';counter=null;dismissed=new Set(state.offers.map(o=>o.id));render();}if(action==='trade-show'){dismissed.clear();render();}if(action==='copy-seat')copy(`${session.room}:${session.token}`,'Private seat key copied.');if(action==='home'){streamController?.abort();state=null;session=null;mode='';history.replaceState({},'','/');render();}return;}
  if(el.dataset.pick){const input=el.closest('form').elements.namedItem(el.dataset.pick);input.value=Math.max(0,Math.min(Number(input.dataset.max),(Number(input.value)||0)+Number(el.dataset.step)));syncPickers();return;}
  if(el.dataset.choose){el.closest('[data-choice]').querySelector('input').value=el.dataset.choose;syncPickers();return;}
  if(el.dataset.resume){try{await enter(saved[el.dataset.resume]);}catch(e){toast(e.message);}return;}
  if(el.dataset.mode){mode=mode===el.dataset.mode?'':el.dataset.mode;counter=null;render();return;}
  if(el.dataset.command)return command(el.dataset.command);
  if(el.dataset.edge)return command('road',{edge:Number(el.dataset.edge)});
  if(el.dataset.vertex)return command(mode==='city'?'city':'settlement',{vertex:Number(el.dataset.vertex)});
  if(el.dataset.hex)return command('robber',{hex:Number(el.dataset.hex)});
  if(el.dataset.card)return command('playCard',{card:el.dataset.card});
  if(el.dataset.victim)return command('steal',{player:Number(el.dataset.victim)});
  if(el.dataset.monopoly)return command('monopoly',{resource:el.dataset.monopoly});
  if(el.dataset.counter){counter=el.dataset.counter;mode='trade';render();return;}
  if(el.dataset.confirm)return command('confirmOffer',{offerId:el.dataset.confirm,player:Number(el.dataset.player)});
  if(el.dataset.decline)return command('declineOffer',{offerId:el.dataset.decline});
  if(el.dataset.accept)return command('acceptOffer',{offerId:el.dataset.accept});
  if(el.dataset.cancel)return command('cancelOffer',{offerId:el.dataset.cancel});
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal='';render();}else if(e.key==='Escape'&&mode&&!e.target.closest?.('form')){mode='';counter=null;render();}if(['Enter',' '].includes(e.key)&&e.target.matches('[data-edge],[data-vertex],[data-hex]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{if(e.target.closest('.picker,[data-choice]'))syncPickers();});
document.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target,data=new FormData(form),bundle=prefix=>Object.fromEntries(R.map(r=>[r,Number(data.get(`${prefix}-${r}`))]));
  try{
    if(form.id==='entry'){const button=form.querySelector('button');button.disabled=true;try{const result=await request(tab==='create'?'/api/rooms':`/api/rooms/${String(data.get('code')).toLowerCase()}/join`,{name:data.get('name'),map:data.get('map'),setup:data.get('setup')});await enter(result);}finally{button.disabled=false;}}
    if(form.id==='bank'&&!(data.get('give')&&data.get('want')))throw new Error('Choose one resource to give and one to receive.');
    if(form.id==='bank')await command('bank',{give:data.get('give'),want:data.get('want')});
    if(form.id==='trade')await command('offer',{give:bundle('give'),want:bundle('want'),...(data.get('counterTo')?{counterTo:data.get('counterTo')}:{})});
    if(form.id==='discard')await command('discard',{resources:bundle('discard')});
    if(form.id==='invention')await command('invention',{resources:bundle('take')});
    if(form.id==='recover'){const [id,token]=String(data.get('key')).trim().split(':');if(!/^[a-f0-9]{12}$/.test(id)||!/^[a-f0-9]{64}$/.test(token))throw new Error('Check the recovery key.');modal='';await enter({room:id,token});}
  }catch(e){toast(e.message);}
});
prune();render();checkSeats();if(room&&saved[room])enter(saved[room]).catch(e=>{state=null;session=null;render();toast(e.message);});
